from admissions_records import *
record('handong-global-university',[route(id='english-majors',label=L('English-taught majors: Global Management, US/International Law, IT, Global Convergence','Англоязычные специальности: Global Management, US/International Law, IT, Global Convergence'),programmeIds=['business','law','computer-science','social-sciences'],applicability=cycle('Spring / Fall 2027',[2027]),english={'requirement':'recommended','ielts':{'accepted':True,'min':None,'recommended':5.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','recommended':85}]},'alternatives':L('New TEPS 285 or TOPIK 4 are recommended documents. Without official scores, language may be assessed at interview after passing document screening.','New TEPS 285 либо TOPIK 4 — рекомендуемые документы. Без официальных баллов язык могут проверить на интервью после прохождения отбора документов.'),'note':L('Cornerstone Scholarship applicants MUST submit a language certificate and separate scholarship form. This scholarship condition is separate from the general admission recommendation.','Кандидаты Cornerstone Scholarship ОБЯЗАТЕЛЬНО представляют языковой сертификат и отдельную стипендиальную форму. Это условие стипендии отдельно от общей вступительной рекомендации.')},academic={'satPolicy':'optional','note':L('The 2027 document table lists SAT/IB/AP/GCE A-level as optional supporting activity/achievement evidence. Recognised schooling is still required; homeschool, online/adult education and GED do not establish eligibility.','Таблица документов 2027 включает SAT/IB/AP/GCE A-level в необязательные подтверждения достижений. Признанное школьное образование всё равно обязательно; домашнее, онлайн/взрослое обучение и GED не подтверждают допуск.')},note=L('First-year admission is undeclared; major selection follows year 1. Only the four listed majors are explicitly 100% English in the guide; this is not an English-language promise for every major.','Первокурсники поступают без специальности; выбор после 1-го года. Только четыре названные специальности прямо обозначены в руководстве как 100% английские; это не обещание английского для всех специальностей.'),documents=[L('Applicant and both parents must be non-Korean nationals; school records, nationality/family evidence, signed forms and required financial documents.','Кандидат и оба родителя должны иметь не корейское гражданство; нужны школьные документы, подтверждения гражданства/родства, подписанные формы и обязательные финансовые документы.')],sources=[S('https://www.handong.edu/ext/bbs/download.dcp?id=16397',L('Handong 2027 international undergraduate guide','Handong: международное руководство бакалавриата 2027'),pages=[5,11,15],access='pdf-read',quote='Language proficiency scores are recommended documents and are required for Cornerstone Scholarship applicants')])], 'Separated recommended 5.5 language evidence from compulsory Cornerstone documents and documented only the four confirmed fully English majors.', ['IELTS variant/sections, new TOEFL scale and exact language mix of other majors remain unconfirmed.'])

record('gist',[route(id='international-undergraduate-reference',label=L('International undergraduate science/engineering — Fall 2026 reference guide','Международный бакалавриат естественных наук/инженерии — справочное руководство Fall 2026'),language='unknown',applicability={'label':'Fall 2026','entryYears':[2026],'status':'previous-cycle','intakes':['fall-2026']},english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None},'toefl':{'accepted':True,'min':None},'alternatives':L('TEPS, TOEIC, Cambridge CAE/CPE, PTE Academic and Duolingo are listed. Test results within two years; the undergraduate guide does not supply a numerical minimum. Graduate IELTS 6.5 must not be imported here.','Указаны TEPS, TOEIC, Cambridge CAE/CPE, PTE Academic и Duolingo. Результаты моложе двух лет; бакалаврское руководство не даёт числового минимума. Магистерский IELTS 6,5 сюда не переносится.'),'waiver':L('The guide exempts native English speakers from the six listed countries. It does not establish a general school-MOI waiver.','Руководство освобождает носителей английского из шести перечисленных стран. Общее освобождение по школьному MOI не установлено.')},academic={'satPolicy':'required-alternatives','note':L('At least one SAT, ACT, GCE A-level, IB, AP, international Olympiad certificate or qualifying national examination report is required in this 2026 undergraduate guide. SAT alone is not the only option.','В этом бакалаврском руководстве 2026 требуется хотя бы один SAT, ACT, GCE A-level, IB, AP, сертификат международной олимпиады либо квалифицирующий национальный экзамен. SAT — не единственный вариант.')},note=L('The guide confirms international bachelor eligibility, but does not establish a wholly English degree or the Fall 2027 rules. Graduate and exchange language pages were excluded.','Руководство подтверждает международный бакалаврский допуск, но не устанавливает полностью английскую степень или правила Fall 2027. Магистерские и обменные языковые страницы исключены.'),sources=[S('https://ewww.gist.ac.kr/iuadm/img/main/2026_Fall_Undergraduate_Admission_Guideline.pdf',L('GIST Fall 2026 international undergraduate guide','GIST: международное руководство бакалавриата Fall 2026'),pages=[1,2,3,4,5,6],access='pdf-read',quote='At least one of the above official test score reports should be submitted.')])], 'Exposed actual undergraduate alternatives and previous-cycle scope instead of reusing graduate minimums.', ['Fall 2027 full undergraduate guide, teaching-language mix, exact IELTS version/minimum/sections and school-MOI waiver remain unconfirmed.'])

record('dgist',[route(id='school-of-undergraduate-studies',label=L('School of Undergraduate Studies — international bachelor route','School of Undergraduate Studies — международный бакалаврский маршрут'),language='multiple',english={'requirement':'optional','ielts':{'accepted':True,'min':None,'noMinimum':True},'toefl':{'accepted':True,'min':None,'noMinimum':True},'alternatives':L('The official government university record lists TOEFL, IELTS, new TEPS, TOEIC, Cambridge CAE/CPE, PTE Academic and Duolingo, with no numerical minimum and two-year test validity. Its department table was last updated in 2024, so this is not a confirmed 2027 rule.','Официальная государственная карточка перечисляет TOEFL, IELTS, новый TEPS, TOEIC, Cambridge CAE/CPE, PTE Academic и Duolingo без числового минимума и со сроком два года. Таблица подразделения обновлена в 2024, поэтому это не подтверждённое правило 2027.'),'note':L('The university’s current complete document checklist lists English proof as optional. This is different from waiving a compulsory numerical minimum.','Текущий полный университетский список документов называет подтверждение английского необязательным. Это отличается от освобождения от обязательного числового порога.')},academic={'satPolicy':'unknown','note':L('Standardised official test reports are optional in the university checklist. Exact accepted SAT/ACT versions and the 2027 guide details were not recovered, so no universal SAT rule is inferred.','Официальные стандартизированные тесты необязательны в университетском списке. Точные принимаемые версии SAT/ACT и детали руководства 2027 не восстановлены, поэтому универсальное правило SAT не предполагается.')},documents=[L('School diploma/expected graduation, transcript, applicant/parents’ passports and parent-child relationship evidence are mandatory; Korean-origin applicants have additional documents.','Обязательны школьный диплом/ожидаемый выпуск, оценки, паспорта кандидата/родителей и подтверждение родства; для корейского происхождения есть дополнительные документы.')],note=L('The official undergraduate department table says above 90% of courses are English. It does not guarantee every required course can be completed in English.','Официальная таблица бакалаврского подразделения указывает свыше 90% предметов на английском. Это не гарантирует возможность пройти каждый обязательный предмет на английском.'),sources=[S('https://www.dgist.ac.kr/iuadm/sub02_04.do',L('DGIST international undergraduate required documents','DGIST: обязательные документы международного бакалавриата'),access='web-html-read'),S('https://www.studyinkorea.go.kr/ko/search/universityInfo.do?tab=univ-basic-info&univCd=100122',L('Official Study in Korea: DGIST undergraduate department record','Официальный Study in Korea: бакалаврское подразделение DGIST'),access='web-html-read')])], 'Separated optional language evidence and an undated/current checklist from the old government test table and the inaccessible 2027 PDF.', ['The university PDF connection failed; exact 2027 test variants, programme language guarantee and scoped academic test policy remain unconfirmed.'])

record('dongguk-university',[route(id='seoul-korean-proof-spring',label=L('Seoul international first-year admission requiring Korean proof — Spring 2027','Seoul: международный приём первокурсников с корейским — весна 2027'),language='unknown',applicability={**cycle('Spring 2027',[2027]),'intakes':['spring-2027']},english={'note':L('The undergraduate notice requires one of its Korean qualifications. An IELTS/TOEFL substitution is not confirmed. The English/tuition table on /eng/page/446 is graduate-level and based on 2021; it is not used as first-year evidence.','Бакалаврское объявление требует одну из корейских квалификаций. Замена через IELTS/TOEFL не подтверждена. Таблица английского/стоимости на /eng/page/446 относится к магистратуре и основана на 2021; она не используется как подтверждение для первокурсника.')},localLanguage=[{'name':'TOPIK / Korean alternatives','requirement':L('TOPIK or iBT TOPIK level 3; Sejong intermediate 3B; specified four-semester language-school completion with attendance conditions; or Dongguk’s in-person level test stage 3. The campus test cannot be taken abroad.','TOPIK либо iBT TOPIK уровень 3; Sejong intermediate 3B; указанное завершение четырёх семестров языковой школы с условиями посещаемости; либо очный тест Dongguk, ступень 3. Кампусный тест нельзя пройти за границей.')}],academic={'satPolicy':'unknown','note':L('The public notice does not establish a SAT/ACT policy; its undergraduate guide must be checked for the specific major.','Публичное объявление не устанавливает политику SAT/ACT; для конкретной специальности нужно руководство бакалавриата.')},note=L('This review establishes a Korean-proof admission route, not a verified wholly English programme. The exact degree teaching language and Fall 2027 rules remain unconfirmed.','Проверен маршрут приёма с корейским, а не полностью английская программа. Точный язык преподавания степени и правила Fall 2027 остаются неподтверждёнными.'),sources=[S('https://en.dongguk.edu/article/INTSTUNOTICE/detail/26766179',L('Dongguk Seoul international undergraduate Spring 2027 notice','Dongguk Seoul: международный бакалаврский приём Spring 2027'),access='web-html-read')])], 'Added the actual Spring 2027 Korean-proof alternatives and explicitly excluded graduate 2021 English-score evidence.', ['Fall 2027 guide, exact programme language, IELTS/TOEFL alternative acceptance and SAT/ACT policy remain unconfirmed.'])
finish()
